<script lang="ts">
  import {comparisonRows,comparisonPoints,comparisonScale,recordedRadioSetting,type ComparedBenchmark,type ObservationBoundary,type ComparisonAxis} from './benchmark-comparison';
  import {goodput,benchmarkCapHit} from './link-benchmark';
  import {formatDistance,formatAccuracy} from './appearance/distance';
  import type {Units} from './appearance/preferences';
  export let results:readonly ComparedBenchmark[]=[];
  export let units:Units='Metric';
  export let configurationFor:(result:ComparedBenchmark,boundary:ObservationBoundary)=>string|undefined=recordedRadioSetting;
  let axis:ComparisonAxis='distance',boundary:ObservationBoundary='end',selectedId='',configuration='';
  $: rows=comparisonRows(results,boundary,configurationFor);
  $: configurations=[...new Set(rows.map(row=>row.configuration))].sort();
  $: if(configuration&&!configurations.includes(configuration))configuration='';
  $: filteredRows=configuration?rows.filter(row=>row.configuration===configuration):rows;
  $: points=comparisonPoints(filteredRows,axis);
  $: scale=comparisonScale(points,axis);
  $: selected=filteredRows.find(row=>row.result.id===selectedId);
  const left=58,right=330,top=18,bottom=195;
  const x=(value:number)=>left+(value-scale.minX)/(scale.maxX-scale.minX)*(right-left);
  const y=(bits:number)=>bottom-bits/scale.divisor/scale.maxY*(bottom-top);
  function xLabel(value:number){return axis==='distance'?formatDistance(value,units):`${Math.round(value)} dBm`;}
  function when(value:number){const d=new Date(value);return Number.isFinite(d.getTime())?d.toLocaleString():'Date unavailable';}
  function outcome(status:string){return status==='complete'?'Complete':status==='cancelled'?'Stopped':'Failed';}
  function rate(row:ComparedBenchmark,direction:'upload'|'download'){const value=row[direction];return value.complete?goodput(value.goodputBitsPerSecond):value.receivedBytes?`Partial · ${goodput(value.goodputBitsPerSecond)}`:'Not measured';}
</script>
<section class="card comparison" aria-labelledby="benchmark-comparison-title">
  <h2 id="benchmark-comparison-title">Compare saved tests</h2>
  <div class="comparison-options"><fieldset class="choice-field"><legend>Compare against</legend><div class="choice-control"><button type="button" aria-pressed={axis==='distance'} onclick={()=>axis='distance'}>Phone separation</button><button type="button" aria-pressed={axis==='signal'} onclick={()=>axis='signal'}>Radio signal</button></div></fieldset><fieldset class="choice-field"><legend>Observation from</legend><div class="choice-control"><button type="button" aria-pressed={boundary==='end'} onclick={()=>boundary='end'}>Test end</button><button type="button" aria-pressed={boundary==='start'} onclick={()=>boundary='start'}>Test start</button></div></fieldset><label class="field configuration-filter">Radio setting<select bind:value={configuration}><option value="">All recorded settings</option>{#each configurations as label}<option value={label}>{label}</option>{/each}</select></label></div>
  {#if points.length}<div class="chart-legend"><span><i class="upload-key"></i>Upload · circle</span><span><i class="download-key"></i>Download · diamond</span></div>
    <svg class="comparison-chart" viewBox="0 0 370 250" role="group" aria-label={`Completed application payload goodput against ${axis==='distance'?'phone GPS separation':'radio RSSI'} recorded at test ${boundary}. ${points.length} measured directions. Select a point or a test below for details.`}>
      {#each [0,.5,1] as fraction}<line x1={left} y1={bottom-fraction*(bottom-top)} x2={right} y2={bottom-fraction*(bottom-top)} class="grid"/><text x={left-7} y={bottom-fraction*(bottom-top)+4} text-anchor="end">{(scale.maxY*fraction).toFixed(1)}</text>{/each}
      <line x1={left} y1={top} x2={left} y2={bottom} class="axis"/><line x1={left} y1={bottom} x2={right} y2={bottom} class="axis"/>
      {#each [0,.5,1] as fraction}{@const value=scale.minX+fraction*(scale.maxX-scale.minX)}<text x={left+fraction*(right-left)} y={bottom+19} text-anchor="middle">{xLabel(value)}</text>{/each}
      <text x="58" y="12">{scale.unit}</text><text x="204" y="243" text-anchor="middle">{axis==='distance'?'Phone separation':'Radio signal · RSSI'}</text>
      {#each points as point(point.id)}<g class="test-point" role="button" tabindex="0" aria-label={`Test ${point.number}, ${point.direction}, ${goodput(point.bitsPerSecond)}, ${xLabel(point.x)}`} onclick={()=>selectedId=point.row.result.id} onkeydown={event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();selectedId=point.row.result.id;}}}>
        <circle cx={x(point.x)} cy={y(point.bitsPerSecond)} r="1" fill="transparent" stroke="transparent" stroke-width="44" vector-effect="non-scaling-stroke"/>
        {#if point.direction==='Upload'}<circle cx={x(point.x)} cy={y(point.bitsPerSecond)} r={selectedId===point.row.result.id?6:4.5} class="upload-point" class:uncertain={point.uncertainDistance}/>{:else}<path d={`M ${x(point.x)} ${y(point.bitsPerSecond)-6} l 6 6 l -6 6 l -6 -6 Z`} class="download-point" class:uncertain={point.uncertainDistance}/>{/if}
      </g>{/each}
    </svg>
    <p class="hint">Recorded measurements, not a predicted range curve. Completed tests only; failed and stopped tests remain below. {axis==='signal'?'Only radio reports mapped to the two tested phones are plotted. RF sample age is unknown.':'Phone GPS is a proxy for nodes carried with phones. Hollow points have a reported fix accuracy larger than the separation.'}</p>
  {:else}<p class="hint comparison-empty" role="status">{results.length?'No completed tests have matching '+(axis==='distance'?'non-mock phone fixes':'mapped radio readings')+' recorded at test '+boundary+'. Older records may lack these observations.':'Run connection tests to compare your saved measurements here.'}</p>{/if}
  {#if selected}<section class="selected-test" aria-live="polite"><h3>Test {selected.number} · {outcome(selected.result.status)}</h3><p>{when(selected.result.completedAt)}</p><p>Upload {rate(selected.result,'upload')} · Download {rate(selected.result,'download')}</p><p>Channel / width: {selected.configuration}</p><p>Radio at test {boundary}: {selected.signal?.rssiDbm!==undefined?`${selected.signal.rssiDbm} dBm · ${selected.signal.direction==='ap-to-station'?'AP → station':'Station → AP'}`:'Unavailable for this phone pair'}</p><p>Phone separation: {selected.distance!==undefined?formatDistance(selected.distance,units):'Unavailable or mock'}</p>{#if selected.observations?.positions}<p class="hint">Fix accuracy: {selected.observations.positions.own?'±'+formatAccuracy(selected.observations.positions.own.accuracy,units):'Your fix unavailable'} / {selected.observations.positions.peer?'±'+formatAccuracy(selected.observations.positions.peer.accuracy,units):'Peer fix unavailable'}. Fix dates: {selected.observations.positions.own?when(selected.observations.positions.own.timestamp):'unavailable'} / {selected.observations.positions.peer?when(selected.observations.positions.peer.timestamp):'unavailable'}.</p>{/if}{#if benchmarkCapHit(selected.result.upload)||benchmarkCapHit(selected.result.download)}<p class="hint">A payload byte limit was reached; actual link capacity may be higher.</p>{/if}</section>{/if}
  {#if rows.length}<details class="comparison-table"><summary>All tests ({filteredRows.length})</summary><p class="hint">Channel and width are shown only when recorded with the test. Current settings never fill gaps in older results.</p><div class="comparison-records">{#each [...filteredRows].reverse() as row(row.result.id)}<button class="comparison-record" class:chosen={selectedId===row.result.id} aria-pressed={selectedId===row.result.id} onclick={()=>selectedId=row.result.id}><strong>Test {row.number} · {outcome(row.result.status)}</strong><span>{when(row.result.completedAt)}</span><span>↑ {rate(row.result,'upload')} · ↓ {rate(row.result,'download')}</span><small>{row.configuration}</small></button>{/each}</div></details>{/if}
</section>
<style>
.comparison{min-width:0}.comparison h2{font-size:19px}.comparison-options{display:grid;grid-template-columns:1fr 1fr;gap:12px}.configuration-filter{grid-column:1/-1}.comparison-options label{min-width:0;font-size:13px}.comparison-options select{width:100%;min-width:0;max-width:100%;min-height:44px}.comparison-chart{display:block;width:100%;height:auto;overflow:visible}.comparison-chart text{font-family:inherit;font-size:18px;fill:var(--muted)}.grid{stroke:var(--line);stroke-dasharray:3 5}.axis{stroke:var(--muted);stroke-width:1}.upload-point{fill:var(--ink);stroke:var(--ink);stroke-width:1.7}.download-point{fill:#a45a24;stroke:#a45a24;stroke-width:1.7}.test-point:focus-visible{outline:none}.test-point:focus-visible .upload-point,.test-point:focus-visible .download-point{stroke:#b57618;stroke-width:4}.upload-point.uncertain,.download-point.uncertain{fill:var(--card)}.test-point{cursor:pointer}.chart-legend{display:flex;gap:16px;flex-wrap:wrap;font-size:12px;margin:16px 0 4px}.chart-legend span{display:flex;align-items:center;gap:7px}.chart-legend i{width:9px;height:9px;display:inline-block;background:var(--ink);border-radius:50%}.chart-legend .download-key{border-radius:0;background:#a45a24;transform:rotate(45deg)}.hint{font-size:12px;line-height:1.6;color:var(--muted)}.selected-test{border-top:1px solid var(--line);padding-top:14px;margin-top:15px}.selected-test h3{font-size:15px}.selected-test p{font-size:13px;line-height:1.5;overflow-wrap:anywhere}.comparison-table summary{min-height:44px;align-content:center;cursor:pointer;font-size:14px;font-weight:650}.comparison-records{display:grid;gap:8px;max-height:390px;overflow:auto}.comparison-record{display:grid;gap:4px;min-height:70px;width:100%;padding:12px;text-align:left;color:inherit;border:1px solid var(--line);border-radius:12px;background:var(--card);font-size:13px;overflow-wrap:anywhere}.comparison-record span,.comparison-record small{font-size:12px;color:var(--muted)}.comparison-record.chosen{border-color:var(--ink)}@media(max-width:350px){.comparison-options{grid-template-columns:1fr}}:global(.app-shell.dark) .download-point{fill:#edb578;stroke:#edb578}:global(.app-shell.dark) .download-point.uncertain{fill:var(--card)}:global(.app-shell.dark) .chart-legend .download-key{background:#edb578}
</style>
